#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	// UPROPERTY keeps the tracker reachable for the garbage collector; a raw
	// pointer was collected (packaged log: GC purge then AddPoints crash).
	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "ScoreTracker in ArenaGameMode.h is a raw UArenaScoreTracker* without UPROPERTY, so the UObject created with NewObject in BeginPlay is unreferenced for the garbage collector and gets purged (log: 'Collecting garbage: 412 objects purged' at 21:05:13); the next OnGoalScored dereferences the dangling pointer in UArenaScoreTracker::AddPoints (EXCEPTION_ACCESS_VIOLATION reading 0xffffffffffffffff). Fix: UPROPERTY() TObjectPtr<UArenaScoreTracker> ScoreTracker.",
  "no_colors_cause": "The palette asset /Game/Data/Palettes/DA_Primary is only loaded by string path via LoadObject at runtime, so the cooker has no hard reference to it and DefaultGame.ini only lists /Game/Data/Effects in DirectoriesToAlwaysCook; the asset is missing from the pak (log: 'Couldn't find file for package /Game/Data/Palettes/DA_Primary', 'Palette is null, using fallback gray'). Fix: add +DirectoriesToAlwaysCook=(Path=\"/Game/Data/Palettes\") in Config/DefaultGame.ini."
}
